SELECT CAST(SUM(CASE WHEN sl."City Name" = 'Burbank' AND substr(so.OrderDate, -2) = '18' THEN so."Order Quantity" ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN substr(so.OrderDate, -2) = '18' THEN so."Order Quantity" ELSE 0 END), 0) AS percentage
FROM "Sales Orders" AS so
JOIN "Store Locations" AS sl ON so._StoreID = sl.StoreID;

